struct algorithm
{
    struct object     hdr;
    enum alg_id       id;
    enum chain_mode   chain_mode;
    ULONG             flags;
    enum ecc_curve_id curve_id;
};

struct asymmetric_key
{
    ULONG bitlen;     /* key strength for ECC keys */
    union
    {
        struct rsa_key rsa;
        struct ecc_key ecc;
        struct dsa_key dsa;
    };
};

enum chain_mode
{
    CHAIN_MODE_CBC,
    CHAIN_MODE_ECB,
    CHAIN_MODE_CFB,
    CHAIN_MODE_CCM,
    CHAIN_MODE_GCM,
};

struct dsa_key
{
    SYMCRYPT_DLKEY   *handle;
    SYMCRYPT_DLGROUP *group;
    UCHAR             seed[20];
    UINT32            count;
};

struct hash
{
    struct object hdr;
    enum alg_id   alg_id;
    ULONG         len;
    ULONG         flags;
    UCHAR        *secret;
    ULONG         secret_len;

    const SYMCRYPT_HASH       *desc;
    SYMCRYPT_HASH_STATE        state;
    SYMCRYPT_HMAC_EXPANDED_KEY hmac;
    SYMCRYPT_HMAC_STATE        hmac_state;
};

struct key
{
    struct object hdr;
    enum alg_id   alg_id;
    ULONG         flags;
    union
    {
        struct symmetric_key s;
        struct asymmetric_key a;
    };
};

static const struct
{
    const WCHAR *name;
    ULONG        class;
    ULONG        object_length;
    ULONG        hash_length;
    ULONG        hash_block_length;
    enum ecc_curve_id curve_id;
    enum chain_mode   chain_mode;
}

struct symmetric_key
{
    enum chain_mode  mode;
    ULONG            block_size;
    UCHAR           *secret;
    ULONG            secret_len;
    UCHAR            vector[BLOCK_LENGTH_AES];
    CRITICAL_SECTION cs;
    union
    {
        struct aes_key  aes;
        struct gcm_key  gcm;
        struct hkdf_key hkdf;
    };
};

union
{
